head.script:
scwin.init = function() {
    widgetContainer.addWidgets([{
            id: "widget1",
            title: "위젯1",
            src: "widget_getSrc_WPF-1561_(WSQ-2561)_content.xml",
            scope: true,
            x: 0,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        },
        {
            id: "widget2",
            title: "위젯2",
            src: "widget_getSrc_WPF-1561_(WSQ-2561)_content.xml",
            scope: true,
            x: 1,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        },
        {
            id: "widget3",
            title: "위젯3",
            src: "widget_getSrc_WPF-1561_(WSQ-2561)_content.xml",
            scope: true,
            hasTitleBar: true,
            x: 2,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        }
    ]);
}
scwin.trigger1_onclick = function(e) {
    //alert( widgetContainer.getWidgetById('widget1').getSrc() );
};
scwin.checkAlert = function() {
    return widgetContainer.getWidgetById('widget1').getSrc();
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 우측의 버튼을 클릭한다.
    //1. Run the sample file and click the button on the right.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. widgetContainer의 경로(SRC)가알림창에보여진다.('widget_getSrc_WPF-1561_(WSQ-2561)_content.xml')이전에는 getSRC() API가 없었음)
    // 1. The path to the widgetContainer (SRC) is shown in the notification window('widget_getSrc_WPF-1561_ (WSQ-2561) _content.xml').(Previously there was no getSRC () API)
    WebSquare.wUnit.addCommand("assert", "scwin.checkAlert() == 'widget_getSrc_WPF-1561_(WSQ-2561)_content.xml'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 31-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
